"use client";
// Independently implemented ROC primitive.
export { MotionGrid } from "./motion-layouts";
import "./motion-grid.css";

"use client";
import { Children, isValidElement, useState, type ComponentProps, type ReactNode, type RefObject } from "react";
import { motion, useMotionValueEvent, useScroll } from "motion/react";
import { Button } from "./button";
import { useRocReducedMotion, useRocTransition } from "./motion-config";
import { cn } from "./utils";
import "./motion-layouts.css";

export function MotionGrid({ children, className, ...props }: ComponentProps<"div">) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  return <div {...props} className={cn("roc-ui roc-motion-grid", className)}>{Children.toArray(children).map((child, index) => <motion.div key={isValidElement(child) ? child.key ?? index : index} layout={!reduce} initial={false} transition={transition}>{child}</motion.div>)}</div>;
}
export function PinnedList({ items, value, onValueChange }: { items: { id: string; label: string; detail?: string }[]; value?: string; onValueChange?: (id: string) => void }) {
  const [local, setLocal] = useState(items[0]?.id);
  const selected = value ?? local, reduce = useRocReducedMotion(), transition = useRocTransition();
  return <div className="roc-ui roc-pinned-list" role="group" aria-label="Pinned items">{items.map(item => <motion.div key={item.id} layout={!reduce} transition={transition} data-selected={item.id === selected}>
    <Button variant="ghost" aria-pressed={item.id === selected} onClick={() => { if (value === undefined) setLocal(item.id); onValueChange?.(item.id); }}>{item.label}</Button>
    <motion.div initial={false} animate={{ height: selected === item.id ? "auto" : 0, opacity: selected === item.id ? 1 : 0 }} transition={transition} inert={selected !== item.id} aria-hidden={selected !== item.id} style={{ overflow: "hidden" }}><p>{item.detail}</p></motion.div>
  </motion.div>)}</div>;
}
export function Spring({ children = "Drag", className }: { children?: ReactNode; className?: string }) {
  const reduce = useRocReducedMotion(), transition = useRocTransition();
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  return <motion.button type="button" className={cn("roc-ui roc-spring", className)} drag dragConstraints={{ top: 0, left: 0, right: 0, bottom: 0 }} dragElastic={reduce ? 0 : 0.35} dragSnapToOrigin
    initial={false} animate={offset} transition={transition} aria-label="Spring: drag or use arrow keys to nudge, release to return"
    onKeyDown={e => { const arrows: Record<string, { x: number; y: number }> = { ArrowLeft: { x: -24, y: 0 }, ArrowRight: { x: 24, y: 0 }, ArrowUp: { x: 0, y: -24 }, ArrowDown: { x: 0, y: 24 } }; if (arrows[e.key]) { e.preventDefault(); setOffset(arrows[e.key]); } }}
    onKeyUp={() => setOffset({ x: 0, y: 0 })} onBlur={() => setOffset({ x: 0, y: 0 })}>{children}</motion.button>;
}
export function ScrollProgress({ container, label = "Reading progress" }: { container?: RefObject<HTMLElement | null>; label?: string }) {
  const { scrollYProgress } = useScroll({ container });
  const [percent, setPercent] = useState(0);
  useMotionValueEvent(scrollYProgress, "change", value => setPercent(Math.round(value * 100)));
  return <div className="roc-ui roc-scroll-progress" role="progressbar" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent}><motion.span style={{ scaleX: scrollYProgress }} /></div>;
}
export function AvatarGroup({ people }: { people: { id: string; name: string; src?: string }[] }) {
  const [selected, setSelected] = useState<string | null>(null);
  return <div className="roc-ui roc-avatar-group" role="group" aria-label="People">{people.map(person => <Button key={person.id} variant="ghost" aria-label={person.name} title={person.name} aria-pressed={selected === person.id} onClick={() => setSelected(selected === person.id ? null : person.id)}>
    {person.src ? <img src={person.src} alt="" /> : <span>{person.name.split(" ").map(n => n[0]).slice(0, 2).join("")}</span>}
  </Button>)}<span role="status">{people.find(p => p.id === selected)?.name}</span></div>;
}
export function Cursor({ children, className }: { children: ReactNode; className?: string }) {
  const [point, setPoint] = useState({ x: 0, y: 0, visible: false });
  const reduce = useRocReducedMotion();
  return <div className={cn("roc-ui roc-cursor-host", className)} onPointerMove={e => {
    if (reduce || e.pointerType !== "mouse" || !matchMedia("(hover: hover) and (pointer: fine)").matches) return;
    const box = e.currentTarget.getBoundingClientRect(); setPoint({ x: e.clientX - box.left, y: e.clientY - box.top, visible: true });
  }} onPointerLeave={() => setPoint(p => ({ ...p, visible: false }))}>{children}<span aria-hidden="true" className="roc-cursor-dot" style={{ translate: `${point.x}px ${point.y}px`, opacity: point.visible ? 1 : 0 }} /></div>;
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: var(--roc-space-2, 8px);
  min-height: var(--roc-control-height, 36px);
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-family: var(--roc-font-control, inherit);
  font-weight: var(--roc-weight-control, 500);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

"use client";
import { type ReactNode } from "react";
import { AnimateUIProvider } from "@animate-ui/react/provider";
import { motionTokens, useShouldReduceMotion, useTempoTransition, type CheckAnimation, type ReducedMotion } from "@animate-ui/react/utils/motion";
import { MotionConfig, type Transition } from "motion/react";

/** ROC's public defaults feed the same provider used by every Animate UI primitive. */
export function RocMotionProvider({ children, pace, reducedMotion, checkAnimation }: {
  children: ReactNode; pace?: number; reducedMotion?: ReducedMotion; checkAnimation?: CheckAnimation;
}) {
  return <AnimateUIProvider tempo={pace === undefined ? undefined : Math.max(0.1, pace)} reducedMotion={reducedMotion} checkAnimation={checkAnimation}>
    <MotionConfig reducedMotion={reducedMotion}>{children}</MotionConfig>
  </AnimateUIProvider>;
}
/** For ROC-only compositions; timings and tempo come from Animate UI. */
export function useRocTransition(kind: "control" | "surface" = "surface"): Transition {
  const transition = useTempoTransition(kind === "control" ? motionTokens.spring.thumb : motionTokens.spring.dialog);
  const reduce = useRocReducedMotion();
  return reduce ? { duration: 0 } : transition;
}
export const useRocReducedMotion = useShouldReduceMotion;

@import "./ui-base.css";
.roc-motion-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 120px), 1fr)); gap: 10px; }
.roc-motion-grid > div { min-width: 0; }
.roc-pinned-list { display: grid; gap: 6px; }
.roc-pinned-list > div { border-bottom: 1px solid var(--roc-line, #ddd); }
.roc-pinned-list .roc-ui-button { justify-content: flex-start; width: 100%; }
.roc-pinned-list [data-selected="true"] { background: var(--roc-marker, #f5f5f5); border-radius: var(--roc-radius, 12px); }
.roc-pinned-list p { margin: 0; padding: 8px 12px 16px; font-size: 12px; line-height: 1.6; color: var(--roc-muted, #777); }
.roc-spring { width: 80px; height: 80px; display: grid; place-items: center; border-radius: 50%; border: 1px solid var(--roc-line, #ddd); background: var(--roc-paper, #fff); cursor: grab; touch-action: none; }
.roc-spring:active { cursor: grabbing; }
.roc-scroll-progress { height: 3px; overflow: hidden; border-radius: 2px; background: var(--roc-marker, #eee); }
.roc-scroll-progress > span { display: block; height: 100%; background: var(--roc-accent, #555); transform-origin: left; }
.roc-avatar-group { display: flex; align-items: center; flex-wrap: wrap; gap: 0; padding: 2px; }
.roc-avatar-group > button { width: 44px; height: 44px; padding: 0; border: 3px solid var(--roc-paper, white); border-radius: 50%; background: var(--roc-marker, #eee); margin-left: -6px; }
.roc-avatar-group > button:first-child { margin-left: 0; }
.roc-avatar-group > button[aria-pressed="true"] { outline: 1px solid var(--roc-ink, #333); z-index: 1; }
.roc-avatar-group img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; }
.roc-avatar-group > span { margin-left: 12px; font-size: 12px; }
.roc-cursor-host { position: relative; overflow: hidden; }
.roc-cursor-dot { position: absolute; top: -5px; left: -5px; width: 10px; height: 10px; border: 1px solid currentColor; border-radius: 50%; pointer-events: none; }
